const input = $json || {};
const source = (input.body && typeof input.body === 'object') ? input.body : input;
const cfg = $item(0).$node['Config'].json || {};

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else cell += ch;
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') {}
      else cell += ch;
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim());
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = r[idx] ?? ''; });
    const hasAny = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAny) out.push(obj);
  }
  return out;
}

function nk(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function pick(obj, aliases) {
  const wanted = new Set((aliases || []).map(nk));
  for (const [k, v] of Object.entries(obj || {})) {
    if (wanted.has(nk(k)) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
}

function stripCsvExt(v) {
  return String(v || '').trim().replace(/\.csv$/i, '');
}

function slugify(v) {
  return stripCsvExt(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function hashString(str) {
  let h = 0;
  const s = String(str || '');
  for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function lit(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  if (typeof v === 'object') {
    const s = JSON.stringify(v).replace(/'/g, "''");
    return `'${s}'::jsonb`;
  }
  const s = String(v).replace(/'/g, "''");
  return `'${s}'`;
}

function splitTags(raw, sourceFileBase) {
  const base = String(raw || '').trim();
  const computed = ['emerald'];
  if (sourceFileBase) computed.push(slugify(sourceFileBase));
  const merged = (base ? base.split(',').map((t) => t.trim()) : []).concat(computed);
  return merged.filter((t) => t).filter((v, i, a) => a.indexOf(v) === i);
}

let records = [];
if (Array.isArray(source.records)) {
  records = source.records;
} else if (typeof source.csvText === 'string' && source.csvText.trim() !== '') {
  records = rowsToObjects(parseCsv(source.csvText));
}
if (!records.length) throw new Error('Provide body.records (array) or body.csvText (CSV string)');

const dryRun = (source.dryRun === undefined || source.dryRun === null) ? !!cfg.defaultDryRun : !!source.dryRun;
const tableName = String(source.tableName || cfg.tableName || 'Emerald_Contacts').trim();
const sourceLabel = String(source.sourceLabel || cfg.sourceLabel || 'emerald_contacts').trim();
const sourceFileOverride = stripCsvExt(source.sourceFile || source.batchUpload || '');

const cols = [
  'record_key','emerald_contact_id','first_name','last_name','full_name','title','roles','seniorities',
  'primary_email','primary_phone','all_known_emails','all_known_phones','contact_linkedin_urls','contact_non_linkedin_urls',
  'contact_city','contact_state','emerald_location_ids','location_legal_names','location_display_names',
  'location_linkedin_urls','location_non_linkedin_urls','company_name','ultimate_hq_names','hq_names',
  'company_linkedin_urls','company_non_linkedin_urls','source_file','tags','source','raw_payload'
];

const updates = cols.filter((c) => !['record_key', 'raw_payload'].includes(c))
  .map((c) => `"${c}" = EXCLUDED."${c}"`)
  .concat(['"raw_payload" = EXCLUDED."raw_payload"', '"updated_at" = NOW()']);

return records.map((rec) => {
  const sourceFileBase = stripCsvExt(sourceFileOverride || pick(rec, ['Source File','source_file','sourceFile','Batch_Upload','batch_upload']));
  const title = pick(rec, ['Titles','Title','title']);
  const primaryEmail = pick(rec, ['Primary Email','primary_email','email']);
  const primaryPhone = pick(rec, ['Primary Phone','primary_phone','phone']);
  const fullName = pick(rec, ['Full Name','full_name']);
  const companyName = pick(rec, ['Company Name(s)','company_name','companyName']);
  const emeraldContactId = pick(rec, ['Emerald Contact ID','emerald_contact_id']);
  const tags = splitTags(pick(rec, ['Tags','tags']), sourceFileBase).join(',');
  const recordKey = emeraldContactId
    || (sourceFileBase && primaryEmail ? `${sourceFileBase}::email::${primaryEmail.toLowerCase()}` : '')
    || (sourceFileBase && primaryPhone ? `${sourceFileBase}::phone::${primaryPhone}` : '')
    || (sourceFileBase && fullName ? `${sourceFileBase}::name::${fullName.toLowerCase()}` : '')
    || `hash::${hashString(JSON.stringify(rec))}`;

  const normalized = {
    record_key: recordKey,
    emerald_contact_id: emeraldContactId || null,
    first_name: pick(rec, ['First Name','first_name','firstName']) || null,
    last_name: pick(rec, ['Last Name','last_name','lastName']) || null,
    full_name: fullName || null,
    title: title || null,
    roles: pick(rec, ['Roles','roles']) || null,
    seniorities: pick(rec, ['Seniorities','seniorities']) || null,
    primary_email: primaryEmail || null,
    primary_phone: primaryPhone || null,
    all_known_emails: pick(rec, ['All Known Emails','all_known_emails']) || null,
    all_known_phones: pick(rec, ['All Known Phones','all_known_phones']) || null,
    contact_linkedin_urls: pick(rec, ['Contact LinkedIn URL(s)','contact_linkedin_urls']) || null,
    contact_non_linkedin_urls: pick(rec, ['Contact non-LinkedIn URL(s)','contact_non_linkedin_urls']) || null,
    contact_city: pick(rec, ['Contact City','contact_city','city']) || null,
    contact_state: pick(rec, ['Contact State','contact_state','state']) || null,
    emerald_location_ids: pick(rec, ['Emerald Location id(s)','emerald_location_ids']) || null,
    location_legal_names: pick(rec, ['Location Legal Name(s)','location_legal_names']) || null,
    location_display_names: pick(rec, ['Location Display Name(s)','location_display_names']) || null,
    location_linkedin_urls: pick(rec, ['Location LinkedIn URL(s)','location_linkedin_urls']) || null,
    location_non_linkedin_urls: pick(rec, ['Location non-LinkedIn URL(s)','location_non_linkedin_urls']) || null,
    company_name: companyName || null,
    ultimate_hq_names: pick(rec, ['Ultimate HQ Name(s)','ultimate_hq_names']) || null,
    hq_names: pick(rec, ['HQ Name(s)','hq_names']) || null,
    company_linkedin_urls: pick(rec, ['Company LinkedIn URL(s)','company_linkedin_urls']) || null,
    company_non_linkedin_urls: pick(rec, ['Company non-LinkedIn URL(s)','company_non_linkedin_urls']) || null,
    source_file: sourceFileBase || null,
    tags,
    source: sourceLabel,
    raw_payload: rec,
  };

  const values = cols.map((c) => lit(normalized[c]));
  const sql = dryRun
    ? 'SELECT 1 AS dry_run;'
    : `INSERT INTO "${tableName}" (${cols.map((c) => `"${c}"`).join(', ')}, "ingested_at", "updated_at")\nVALUES (${values.join(', ')}, NOW(), NOW())\nON CONFLICT (record_key) DO UPDATE SET\n${updates.join(',\n')};`;

  return { json: { dryRun, tableName, sourceLabel, normalized, upsertSql: sql } };
});

const items = $input.all();
const dryRun = items.length ? !!items[0].json.dryRun : true;
const tableName = items.length ? items[0].json.tableName : 'Emerald_Contacts';
return [{ json: { ok: true, dryRun, table: tableName, rowsProcessed: items.length, writesExecuted: dryRun ? 0 : items.length, note: dryRun ? 'No rows were written. Set body.dryRun=false after validation to write.' : 'Rows written to Postgres.' } }];

